from pathlib import Path
import json,shutil,re,html,hashlib,zipfile
p=Path('ArtDirection/EpicCitiesBuilt-20261025');p.mkdir(exist_ok=True)
marker=Path('Logs/Validation/EpicCityRuntime-started.txt');done=Path('Logs/Validation/EpicCityRuntime-complete.txt')
assert marker.exists() and marker.read_text(encoding='utf-8-sig').startswith('Version=4'),'Waiting for final production run'
assert done.exists() and done.stat().st_mtime>=marker.stat().st_mtime and 'failures=0 runtimeErrors=0' in done.read_text(encoding='utf-8-sig'),'Production validation not complete/passing'
counts=json.loads((p/'Counts.json').read_text(encoding='utf-8'));e=lambda x:html.escape(str(x));cards=[];tables=[]
for c in counts:
 n=c['number'];report=Path(f'Logs/Validation/EpicCity-{n:02}-game.txt');assert report.exists() and report.stat().st_mtime>=marker.stat().st_mtime
 text=report.read_text(encoding='utf-8-sig');assert 'REVIEW' not in text and 'Wave completed=True' in text and 'validRoundtrip=True' in text,text
 folder=p/'Captures';folder.mkdir(exist_ok=True);evidence=p/'Evidence';evidence.mkdir(exist_ok=True)
 shutil.copy2(report,evidence/report.name)
 images=[]
 for state,label in [('intact','Intact · production Game'),('tsunami','After default-force tsunami'),('impact','Separate stronger demolition')]:
  f=Path(f'Logs/Validation/EpicCity-{n:02}-{state}.png');assert f.exists() and f.stat().st_mtime>=marker.stat().st_mtime
  shutil.copy2(f,folder/f.name);images.append(f'<figure><a href="Captures/{f.name}"><img src="Captures/{f.name}" alt="{e(c["name"])}: {label}" loading="lazy"></a><figcaption>{label}</figcaption></figure>')
 quiet=re.search(r'32 bots / quiet.*average=([\d.]+)FPS',text);wave=re.search(r'32 bots \+ tsunami.*average=([\d.]+)FPS',text)
 q=quiet.group(1) if quiet else '—';w=wave.group(1) if wave else '—'
 tables.append(f'<tr><th><a href="#map-{n}">{n:02} {e(c["name"])}</a></th><td>{c["bodies"]}</td><td>{c["shapes"]}</td><td>{c["elevated"]}</td><td>{q}</td><td>{w}</td></tr>')
 cards.append(f'<article id="map-{n}"><h2>{n:02} · {e(c["name"])}</h2><p>{c["sites"]} districts · {c["bodies"]} structural bodies · {c["shapes"]} collision shapes · {c["elevated"]} elevated connections · {c["joints"]} joints</p><div class="shots">'+''.join(images)+f'</div><details><summary>Actual runtime report</summary><pre>{e(text)}</pre></details></article>')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Deadly Jenga · Ten Built Cities</title><style>body{margin:0;background:#101a29;color:#e9f2ff;font:17px/1.6 system-ui,sans-serif}main{max-width:1550px;margin:auto;padding:45px 5vw}h1{font-size:48px;line-height:1.1}h2{margin-bottom:8px}a{color:#9ff0cb}header p{max-width:1050px}.note{border-left:4px solid #ffc985;padding:18px;background:#263046}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:15px}td,th{text-align:left;padding:12px;border-bottom:1px solid #40516c}article{border-top:1px solid #40516c;padding-top:24px;margin:40px 0}.shots{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}figure{margin:0}img{width:100%;height:auto}figcaption{color:#b8c9e0;font-size:14px}details{padding:18px;background:#17263b;margin-top:18px}summary{cursor:pointer;color:#cdb9ff}pre{white-space:pre-wrap;font:14px/1.6 ui-monospace,monospace}li{margin:12px 0}@media(max-width:900px){.shots{grid-template-columns:1fr}h1{font-size:35px}}</style></head><body><main><header><p>DEADLY JENGA · BUILT MAPS · OCTOBER 2026</p><h1>Ten connected epic cities</h1><p>All ten are separate selectable maps. In the lobby, choose Mode → Map → <b>Epic connected cities</b>. In the desktop demo menu, choose Game Controls → Maps; the VR map menu uses the same category.</p><p><a href="EpicCitiesBuiltReview.zip" download>Download screenshots and evidence</a> · <a href="../EpicCityReview-20261025/index.html">Original concept review</a></p><p class="note">These are actual production Game captures. The ordinary tsunami and stronger reset/demolition trial are separate tests. Desktop Editor timings are specific to this laptop and camera. The measured frame rates remain low: these builds pass the listed behavior checks, but are not performance-certified. No Quest or two-player certification is claimed.</p></header><div class="table"><table><thead><tr><th>Map</th><th>Bodies</th><th>Shapes</th><th>Elevated links</th><th>32-bot quiet FPS</th><th>32-bot wave FPS</th></tr></thead><tbody>TABLE</tbody></table></div><h2>What was built</h2><p>Independently moving multi-floor sections, real open stair slots, clear climbing ribs, bearing rafts, loose bridges, physical intermediate supports, and one continuous shore-matched terrain collider per island. Caldera, Lantern Ravine and Rising Spine have actual ground elevation. Bookfall has three hinged wings with receiving feet and physical catches; Three Hearts includes the drop-stop assembly.</p><p>The images were interpreted as playable structures rather than copied as exact engineering drawings. Multi-floor cassettes move as units; their individual stairs, piers and floor strips do not each fracture separately. Some proposed bridges remain ground streets when a safe bearing route cannot fit. Heights and spans were adapted to verified collision clearance.</p><h2>Verification and limits</h2><ul><li>All ten passed native geometry, settling and full-size ascent sampling; a focused relay follow-up is retained separately from the earlier full report.</li><li>Production reports below cover real survivor motors, 32 bots, a default-force tsunami, stronger demolition, layout roundtrip and reset.</li><li>No Core contract, global solver setting, package or gameplay scene was changed. Existing maps were preserved.</li><li>Mode-specific competitive balancing and real Quest/multiplayer sessions remain follow-up work. A large playable map is not automatically balanced for every population and mode.</li></ul>CARDS<footer><a href="Evidence/NativeFinal.txt">Native final results</a> · <a href="Evidence/NativeFullRaw.txt">Raw full run</a> · <a href="Evidence/NativeRelayRecheck.txt">Focused relay recheck</a> · <a href="Evidence/SourceSHA256.json">Source hashes</a></footer></main></body></html>'''.replace('TABLE',''.join(tables)).replace('CARDS',''.join(cards))
(p/'index.html').write_text(page,encoding='utf-8')
(p/'Evidence/SourceSHA256.json').write_text(json.dumps({str(f):hashlib.sha256(f.read_bytes()).hexdigest() for f in Path('Assets/_DeadlyJenga/World/Maps/Scripts').glob('EpicCity*.cs')},indent=2),encoding='utf-8')
shutil.copy2(done,p/'Evidence'/done.name)
with zipfile.ZipFile(p/'EpicCitiesBuiltReview.zip','w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
 for f in p.rglob('*'):
  if f.is_file() and f.suffix!='.zip':z.write(f,f.relative_to(p))
print('Built review with all 30 production captures.')
